import json
from collections import deque

def find_connected_components(grid, color):
    rows = len(grid)
    cols = len(grid[0])
    visited = set()
    components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == color and (r, c) not in visited:
                component = []
                queue = deque([(r, c)])
                visited.add((r, c))

                while queue:
                    cr, cc = queue.popleft()
                    component.append((cr, cc))

                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == color and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                queue.append((nr, nc))

                components.append(component)
    return components

def transform(grid):
    # Find background color (most common)
    rows = len(grid)
    cols = len(grid[0])
    from collections import Counter
    all_cells = [cell for row in grid for cell in row]
    background = Counter(all_cells).most_common(1)[0][0]

    rows = len(grid)
    cols = len(grid[0])
    visited = set()

    # Find connected components
    components_by_color = {}
    for color in range(10):
        if color == background:
            continue

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == color and (r, c) not in visited:
                    component = []
                    queue = deque([(r, c)])
                    visited.add((r, c))

                    while queue:
                        cr, cc = queue.popleft()
                        component.append((cr, cc))

                        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < rows and 0 <= nc < cols:
                                if grid[nr][nc] == color and (nr, nc) not in visited:
                                    visited.add((nr, nc))
                                    queue.append((nr, nc))

                    if color not in components_by_color:
                        components_by_color[color] = []
                    components_by_color[color].append(component)

    # Create output grid
    output = [row[:] for row in grid]

    # Apply rule: if all cells in a component are on the top row, change to 0
    for color, color_components in components_by_color.items():
        for component in color_components:
            if all(r == 0 for r, c in component):
                # Change this component to 0
                for r, c in component:
                    output[r][c] = 0

    return output

