# Let me try to simulate the rule: 0s connected to each other or to something become 6
# and neighbor them

from collections import deque, Counter

def get_component(grid, start_r, start_c, include_colors, colors_to_exclude=None):
    rows, cols = len(grid), len(grid[0])
    if colors_to_exclude is None:
        colors_to_exclude = set()

    visited = set()
    component = []
    queue = deque([(start_r, start_c)])
    visited.add((start_r, start_c))

    while queue:
        r, c = queue.popleft()
        component.append((r, c))
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited:
                if grid[nr][nc] in include_colors:
                    visited.add((nr, nc))
                    queue.append((nr, nc))
    return component

def demo2_transform(grid):
    """
    Hypothesis: 0s that are in a group connected to the right edge become 6s
    and expand into adjacent 2s. 0s not connected to right edge stay 0.
    """
    rows, cols = len(grid), len(grid[0])

    # Find all connected components of 0s
    zero_components_by_r = {}
    visited = set()
    zero_components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and (r, c) not in visited:
                comp = get_component(grid, r, c, {0})
                zero_components.append(comp)
                visited.update(comp)

    print(f"\nFound {len(zero_components)} zero components in demo 2 input")
    for i, comp in enumerate(zero_components):
        print(f"Component {i}: {len(comp)} zeros, first row={zero_components[i][0][0]}, last row={tuple(max(r for r, c in comp))}")
        # Check if component reaches right edge
        touches_right = any(c == cols - 1 for r, c in comp)
        print(f"  Touches right edge: {touches_right}")

        # Check if any cell in component is adjacent to a non-0, non-2 cel
        adjacent_to_other = False
        for r, c in comp:
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] not in {0, 2}:
                        adjacent_to_other = True
                        print(f"  Component {i} cell ({r},{c})=0 adjacent to {grid[nr][nc]} at ({nr},{nc})")
                        break
            if adjacent_to_other:
                break

        if not adjacent_to_other:
            print(f"  Component {i} is isolated (only 0s) - count: {sum(1 for v in grid[r][c] for v in [0] for r in [r] for c in [c] if r in [r] and c in [c])}")

    return zero_components

