def find_components_by_color(grid):
    rows, cols = len(grid), len(grid[0])
    bg = 3  # Background
    visited = set()
    components = {}  # color -> list of components

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg and (r, c) not in visited:
                color = grid[r][c]
                comp = []
                queue = [(r, c)]
                comp_set = {(r, c)}
                while queue:
                    cr, cc = queue.pop()
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == color and (nr, nc) not in comp_set:
                            comp_set.add((nr, nc))
                            queue.append((nr, nc))

                components.setdefault(color, []).append(comp)
                visited.update(comp)

    return components

