from collections import deque

def get_component(grid, start_r, start_c, target_color):
    visited = set()
    q = deque([start_r, start_c])
    comp = []
    rmax, cmax = len(grid), len(grid[0])
    while q:
        r = q.popleft()
        c = q.popleft()
        in_comp = (r, c)
        comp.append(in_comp)
        if in_comp in visited or (r < 0 or c < 0 or r >= rmax or c >= len(grid[r])):
            continue
        visited.add(in_comp)
    return comp

