def get_target_color(grid, bg=None):
    """Get 2nd most frequent non-background color"""
    if bg is None:
        all_cg = [v for row in grid for v in row]
        bg = Counter(all_cg).most_common(1)[0][0]

    all_cg = [v for row in grid for v in row]
    freq = Counter(all_cg)
    non_bg = sorted([c for c in freq if c != bg], key=lambda x: -freq[x])
    return non_bg[1] if len(non_bg) >= 2 else non_bg[0], bg

def transform(grid):
    result = [row[:] for row in grid]
    rows, cols = len(result), len(result[0]) if result else 0

    target, bg = get_target_color(result)

    for r in range(rows):
        for c in range(cols):
            color = result[r][c]
            if color == bg:
                continue

            is_single = True
            neighbor_count = 0
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if result[nr][nc] == color:
                        is_single = False
                        break
                    neighbor_count += 1

            if not is_single:
                continue

            if neighbor_count != 4:
