            all_neighbors_bg = True
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if result[nr][nc] != bg:
                        all_neighbors_bg = False
                        break

            if all_neighbors_bg:
